{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Tetrabenazine, the closest structural analogue (Morgan 0.3731), has a mean absolute oral bioavailability of only 4.9% in patients, showing that the dimethoxybenzene-fused nitrogenous ring system is associated with extensive first-pass metabolism and low systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Almorexant, which shares a dimethoxyisoquinoline amide core, has an absolute oral bioavailability of 11.2% in healthy subjects, supporting low F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Donepezil, a dimethoxyaromatic basic amine, has near-complete oral bioavailability (~100%), indicating that basicity and dimethoxy substitution do not inherently preclude high F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Valbenazine, a tetrabenazine analogue, achieves ~49% oral bioavailability, but this is via a prodrug ester strategy not present in the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The closest analogue, tetrabenazine, has very low oral bioavailability (4.9%), and almorexant with a similar dimethoxyisoquinoline amide core also shows low F (11%). Although donepezil and valbenazine demonstrate that related dimethoxyaromatic basic amines can have high F, their structural differences (smaller size, prodrug ester) reduce transferability. The query's low neutral fraction, moderate logD, high molecular weight, and multiple metabolic soft spots support a low F prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities to all evidence molecules are low (<0.38), limiting transferability.",
    "The query's lactam amide versus tetrabenazine's ketone may alter metabolic stability in an unknown direction.",
    "The effect of the basic side chain and low neutral fraction on permeability is not directly covered by the analogues.",
    "No data on P-gp efflux or specific CYP-mediated first-pass metabolism for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

